#define rot(x) mat2(cos(x+vec4(0,11,33,0)))
//formula for creating colors;
#define H(h)  ( cos( h/1.7 + 5.1*vec3(2,3,4) )*.6 + .3 )
#define H2(h) ( cos( h*h/2. + vec3(1,2,3) )*.7 + .2 )
//formula for mapping scale factor 
#define M(c)  log(1.+c)
#define R iResolution
#define C(x) x = x>1. ? x=2.-x : (x<-1. ? -2.-x : x)

void mainImage( out vec4 O, vec2 U) {

    O = vec4(0);    
    vec3 c=vec3(0);
    vec4 rd = normalize( vec4(U-.5*R.xy, .8*R.y, .1*R.y))*150.; 
    float sc,dotp,totdist=0.,t=13.3, tt=iTime;   
    float iters = 4.;

    rd.xz *= rot(-.4);

    for (float i=0.; i<60.; i++) {       
        vec4 p = vec4( rd*totdist);            
        p.xyz += vec3(-t/3.,-t*2.-tt,t+7.);        
        p.yzw = p.xyz;
        p.zw *= rot(1.);
        p.xz = cos(p.xz/3.);
        p.xw = sin(p.xw);
        p.xw *= rot(  .3*sin(tt/2.));

        sc = 1.; 
        for (float j=0.; j<iters; j++) {

            C(p.x); C(p.y); C(p.z); C(p.w);  
            p *= .65;
            p -= .5*p;
            dotp = max(1./dot(p.xz,p.xz),.2);
            sc *= dotp;
            p = 2. *p * dotp;                    
        }

        float dist = abs( length(p.zw)-.001)/sc ; 
        float stepsize = dist/40. ;     
        totdist += stepsize;                 

        c += (
               .01* H2(  atan( p.z, p.w ))  
             + .05* H(M(sc))
             ) * exp(-i*i*stepsize*stepsize*2e3);
    }

    c = 1. - exp(-c*c);

    O = ( vec4(c,0) );

}
